changeSet.sql:
INSERT INTO permissions (name, description) VALUES ('plugin_deviceinfo_access', 'Имеет доступ к детальной и динамической информации об устройствах');
INSERT INTO userrolepermissions (roleId, permissionId)
    SELECT id, currval('permissions_id_seq')
    FROM userroles;

CREATE TABLE plugin_deviceinfo_settings (
    id INT NOT NULL AUTO_INCREMENT,
    customerId INT NOT NULL,
    dataPreservePeriod INT NOT NULL DEFAULT 30,
    CONSTRAINT plugin_deviceinfo_settings_pr_key PRIMARY KEY (id),
    CONSTRAINT plugin_deviceinfo_settings_customerId_fkey FOREIGN KEY (customerId) REFERENCES customers(id) ON DELETE CASCADE
) ENGINE=InnoDB;
ALTER TABLE plugin_deviceinfo_settings ADD CONSTRAINT plugin_deviceinfo_settings_customer_unique UNIQUE (customerId);

ALTER TABLE plugin_deviceinfo_deviceparams_device ADD COLUMN usbStorage BOOLEAN;
ALTER TABLE plugin_deviceinfo_deviceparams_device ADD COLUMN memoryTotal INT;
ALTER TABLE plugin_deviceinfo_deviceparams_device ADD COLUMN memoryAvailable INT;

changeSet.rollback:
ALTER TABLE plugin_deviceinfo_deviceparams_device DROP COLUMN usbStorage;
ALTER TABLE plugin_deviceinfo_deviceparams_device DROP COLUMN memoryTotal;
ALTER TABLE plugin_deviceinfo_deviceparams_device DROP COLUMN memoryAvailable;
